import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import YouTube from 'react-youtube';
import WebSocketService from '../services/websocket';
import './Room.css';

const Room = () => {
  const { roomId } = useParams();
  const navigate = useNavigate();
  const [participants, setParticipants] = useState([]);
  const [player, setPlayer] = useState(null);
  const [isHost, setIsHost] = useState(false);
  const [userRole, setUserRole] = useState('PARTICIPANT');
  const [currentVideoId, setCurrentVideoId] = useState('dQw4w9WgXcQ');
  const [newVideoUrl, setNewVideoUrl] = useState('');
  const [chatMessages, setChatMessages] = useState([]);
  const [chatInput, setChatInput] = useState('');
  const [isSeeking, setIsSeeking] = useState(false);
  
  const userId = localStorage.getItem('userId');
  const username = localStorage.getItem('username');
  const wsService = useRef(null);

  useEffect(() => {
    if (!userId || !username) {
      navigate('/');
      return;
    }

    // Initialize WebSocket connection
    wsService.current = new WebSocketService();
    wsService.current.connect(roomId, userId, username, {
      onPlay: (data) => {
        if (player && player.getPlayerState() !== 1) {
          player.playVideo();
          addChatMessage('system', '▶️ Playback resumed');
        }
      },
      onPause: (data) => {
        if (player && player.getPlayerState() === 1) {
          player.pauseVideo();
          addChatMessage('system', '⏸️ Playback paused');
        }
      },
      onSeek: (data) => {
        if (player) {
          player.seekTo(data.time, true);
          addChatMessage('system', `⏩ Jumped to ${Math.floor(data.time)}s`);
        }
      },
      onVideoChange: (data) => {
        setCurrentVideoId(data.videoId);
        if (player) {
          player.loadVideoById(data.videoId);
          addChatMessage('system', '🎬 Video changed!');
        }
      },
      onUserJoined: (data) => {
        setParticipants(prev => [...prev, data]);
        addChatMessage('system', `✨ ${data.username} joined the party!`);
        
        // Show welcome message for new user
        if (data.userId === userId) {
          setTimeout(() => {
            addChatMessage('system', `🎉 Welcome to the party, ${username}! ${isHost ? 'You are the HOST!' : 'Enjoy the show!'}`);
          }, 500);
        }
      },
      onUserLeft: (data) => {
        setParticipants(prev => prev.filter(p => p.userId !== data.userId));
        addChatMessage('system', `👋 ${data.username} left the party!`);
      },
      onRoleAssigned: (data) => {
        setParticipants(prev => 
          prev.map(p => p.userId === data.userId ? {...p, role: data.role} : p)
        );
        if (data.userId === userId) {
          setUserRole(data.role);
          setIsHost(data.role === 'HOST');
          addChatMessage('system', `👑 You are now a ${data.role}!`);
        } else {
          const user = participants.find(p => p.userId === data.userId);
          if (user) {
            addChatMessage('system', `👑 ${user.username} is now a ${data.role}!`);
          }
        }
      },
      onParticipantRemoved: (data) => {
        if (data.userId === userId) {
          alert('You have been removed from the room by the host!');
          navigate('/');
        } else {
          setParticipants(prev => prev.filter(p => p.userId !== data.userId));
          const user = participants.find(p => p.userId === data.userId);
          if (user) {
            addChatMessage('system', `🚫 ${user.username} was removed from the room!`);
          }
        }
      },
      onChat: (data) => {
        addChatMessage(data.username, data.message);
      },
      onError: (error) => {
        console.error('WebSocket error:', error);
        alert('⚠️ Connection error. Please refresh the page.');
      }
    });

    return () => {
      if (wsService.current) {
        wsService.current.disconnect();
      }
    };
  }, [roomId, userId, username, navigate, player]);

  const addChatMessage = (sender, message) => {
    setChatMessages(prev => [...prev, { sender, message, timestamp: new Date() }]);
  };

  const onPlayerReady = (event) => {
    setPlayer(event.target);
    addChatMessage('system', '🎥 Player is ready!');
  };

  const onPlayerStateChange = (event) => {
    if (!isSeeking && (userRole === 'HOST' || userRole === 'MODERATOR')) {
      if (event.data === 1) { // Playing
        wsService.current.sendPlay(roomId, userId);
      } else if (event.data === 2) { // Paused
        wsService.current.sendPause(roomId, userId);
      }
    }
  };

  const handleSeek = (e) => {
    if (player && (userRole === 'HOST' || userRole === 'MODERATOR')) {
      const time = parseFloat(e.target.value);
      setIsSeeking(true);
      player.seekTo(time);
      wsService.current.sendSeek(roomId, userId, time);
      setTimeout(() => setIsSeeking(false), 100);
    }
  };

  const handleChangeVideo = () => {
    const videoId = extractVideoId(newVideoUrl);
    if (videoId) {
      wsService.current.sendChangeVideo(roomId, userId, videoId);
      setNewVideoUrl('');
      addChatMessage('system', `🎬 Changing video to: ${videoId}`);
    } else {
      alert('❌ Invalid YouTube URL. Please paste a valid YouTube link!');
    }
  };

  const extractVideoId = (url) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
  };

  const assignRole = (targetId, role) => {
    wsService.current.sendAssignRole(roomId, userId, targetId, role);
  };

  const removeParticipant = (targetId) => {
    if (window.confirm('⚠️ Are you sure you want to remove this participant?')) {
      wsService.current.sendRemoveParticipant(roomId, userId, targetId);
    }
  };

  const sendChat = () => {
    if (chatInput.trim()) {
      wsService.current.sendChat(roomId, userId, username, chatInput);
      setChatInput('');
    }
  };

  const copyRoomCode = () => {
    navigator.clipboard.writeText(roomId);
    alert('📋 Room code copied to clipboard! Share it with friends!');
  };

  const opts = {
    height: '450',
    width: '100%',
    playerVars: {
      autoplay: 0,
      controls: 1,
      modestbranding: 1,
      rel: 0,
      showinfo: 0,
    },
  };

  const canControl = userRole === 'HOST' || userRole === 'MODERATOR';

  return (
    <div className="room-container">
      <div className="room-header">
        <h2>
          🎬 YouTube Watch Party
          <span className="room-code" onClick={copyRoomCode} style={{ cursor: 'pointer' }}>
            📋 {roomId}
          </span>
        </h2>
        <button className="btn btn-danger" onClick={() => navigate('/')}>
          🚪 Leave Room
        </button>
      </div>

      <div className="room-content">
        <div className="video-section">
          <YouTube
            videoId={currentVideoId}
            opts={opts}
            onReady={onPlayerReady}
            onStateChange={onPlayerStateChange}
          />
          
          {canControl && (
            <div className="controls">
              <button onClick={() => player?.playVideo()}>
                ▶ Play
              </button>
              <button onClick={() => player?.pauseVideo()}>
                ⏸ Pause
              </button>
              <input
                type="range"
                min="0"
                max="100"
                onChange={handleSeek}
                disabled={!player}
                title="Seek video"
              />
              <div className="video-change">
                <input
                  type="text"
                  placeholder="🔗 Paste YouTube URL here..."
                  value={newVideoUrl}
                  onChange={(e) => setNewVideoUrl(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && handleChangeVideo()}
                />
                <button onClick={handleChangeVideo}>
                  🎬 Change Video
                </button>
              </div>
            </div>
          )}
        </div>

        <div className="sidebar">
          <div className="participants-section">
            <h3>
              👥 Participants 
              <span style={{ fontSize: '14px', color: '#667eea' }}>
                ({participants.length})
              </span>
            </h3>
            <ul>
              {participants.map((p, index) => (
                <li key={p.userId} className="participant-item" style={{ animationDelay: `${index * 0.05}s` }}>
                  <span className="participant-name">
                    {p.username}
                    {p.userId === userId && ' (You)'}
                  </span>
                  <span className={`role-badge role-${p.role.toLowerCase()}`}>
                    {p.role === 'HOST' && '👑 '}
                    {p.role === 'MODERATOR' && '⭐ '}
                    {p.role === 'PARTICIPANT' && '👤 '}
                    {p.role}
                  </span>
                  {isHost && p.userId !== userId && (
                    <div className="participant-actions">
                      {p.role !== 'MODERATOR' && (
                        <button onClick={() => assignRole(p.userId, 'MODERATOR')}>
                          ⭐ Make Moderator
                        </button>
                      )}
                      {p.role !== 'PARTICIPANT' && (
                        <button onClick={() => assignRole(p.userId, 'PARTICIPANT')}>
                          👤 Demote
                        </button>
                      )}
                      <button onClick={() => removeParticipant(p.userId)}>
                        🚫 Remove
                      </button>
                    </div>
                  )}
                </li>
              ))}
            </ul>
          </div>

          <div className="chat-section">
            <h3>💬 Live Chat</h3>
            <div className="chat-messages">
              {chatMessages.map((msg, idx) => (
                <div key={idx} className={`chat-message ${msg.sender === 'system' ? 'system' : ''}`}>
                  <strong>
                    {msg.sender === 'system' ? '📢' : msg.sender}:
                  </strong>{' '}
                  {msg.message}
                </div>
              ))}
              {chatMessages.length === 0 && (
                <div style={{ textAlign: 'center', color: '#999', padding: '20px' }}>
                  💬 No messages yet. Start the conversation!
                </div>
              )}
            </div>
            <div className="chat-input">
              <input
                type="text"
                placeholder="Type your message..."
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && sendChat()}
              />
              <button onClick={sendChat}>
                📤 Send
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Room;
